"""Plotting helpers for the reports generated by the forecasting pipeline."""
from pathlib import Path

import matplotlib.pyplot as plt


def save_demand_history(frame, output: str | Path) -> Path:
    output = Path(output); output.parent.mkdir(parents=True, exist_ok=True)
    fig, ax = plt.subplots(figsize=(10, 4))
    ax.plot(frame["timestamp"], frame["demand"], linewidth=0.8)
    ax.set(title="Illustrative electricity demand", xlabel="Time", ylabel="Demand (synthetic kWh)")
    fig.tight_layout(); fig.savefig(output); plt.close(fig)
    return output
